query($searchQuery: SearchQueryInput!, $variant: String) {
  typeAhead(searchQuery: $searchQuery, variant: $variant) {
    results {
      id
      name
      displayType
      type
      subType
      url
      canonical
      mobileUrl
      center
      uniqueId
      crossCityUuid
      displaySubType
    }
    defaultUrl
    isCrossCitySearch
  }
}
